					groupMenus[parent].Add(effect.Group, DebugMenu.Create(effect.Group, parent));

				parent = groupMenus[parent][effect.Group];
			}

			parent.AddItem(effect.Label, reference =>
			{
				var tuple = ((string, string, string, int))reference;
				var type = tuple.Item3;

				var loadParam = new EffectManager.LoadParam();
				loadParam.AssetBundleName = "effect/prefab/" + tuple.Item2;
				loadParam.AssetName = System.IO.Path.GetFileNameWithoutExtension(loadParam.AssetBundleName);
				loadParam.PoolCount = tuple.Item4;

				EffectManager.Instance.Load(new EffectManager.LoadParam[] { loadParam }, (effectData, isAllLoaded) =>
				{
					var attachedTransform = _simpleCamera.gameObject.transform;
					if (type == "Screen")
						attachedTransform = _screenEffectCamera.transform;

					var position = new Vector3(0.0f, 0.0f, 2.0f);
					var effectInstance = EffectManager.Instance.Create(effectData, position, Quaternion.identity, attachedTransform);

					if (type == "Weather")
					{
						var camera = _simpleCamera.GetComponent<Camera>();
						var follower = effectInstance.gameObject.GetComponent<CameraFollower>();
						if (follower != null)
							follower.SetCamera(camera);
					}

					effectInstance.Play(instance =>
					{
						_effecctInstances.Remove(instance);
						SetupEffectStopMenu();
					});
					_effecctInstances.Add(effectInstance);
					AddEffectStopInstance(effectInstance);
				});
			}, (effect.Label, effect.AssetBundleName, effect.Type, effect.PoolCount));
		}

		_effectStopMenu = DebugMenu.Create("停止", effectMenu);
		effectMenu.AddItem("全停止", reference => EffectManager.Instance.RemoveInstances(true), (string.Empty, (GameObject)null));
	}
