	private void CreateAudioMenu(global::SmartPoint.Components.DebugMenu.MenuInstance parentMenu) {
		var audioMenu = DebugMenu.Create("オーディオ", parentMenu);

		foreach (var group in _audioData.Group)
			_audioGroupDict.Add(group.Group, DebugMenu.Create(group.Group, audioMenu));

		foreach (var data in _audioData.Bgm)
		{
			DebugMenu.MenuInstance menu = null;
			_audioGroupDict.TryGetValue(data.Group, out menu);
			if (menu != null)
			{
				menu.AddItem(data.Label, reference =>
				{
					AudioManager.Instance.SetBgmEvent(AudioManager.Instance.GetIdByName(data.EventName), false);
				}, null, null);
			}
		}

		foreach (var se in _audioData.Se)
		{
			var bankName = se.BankName;
			var playEventId = AudioManager.Instance.GetIdByName(se.PlayEventName);
			var stopEventId = AudioManager.Instance.GetIdByName(se.StopEventName);

			DebugMenu.MenuInstance menu = null;
			_audioGroupDict.TryGetValue(se.Group, out menu);
			if (menu != null)
			{
				menu.AddItem(string.Format("{0}:{1}", se.Label, playEventId), reference =>
				{
					if (AudioManager.Instance.FindAudioData(bankName) == null)
						AudioManager.Instance.Load(new AudioManager.LoadParam { bankName = bankName }, audioData => PlaySe(playEventId, stopEventId));
					else
						PlaySe(playEventId, stopEventId);
				}, null, null);
			}
		}

		foreach (var data in _audioData.Voice)
		{
			var playEventId = AudioManager.Instance.GetIdByName(data.PlayEventName);
			var stopEventId = AudioManager.Instance.GetIdByName(data.StopEventName);

			DebugMenu.MenuInstance menu = null;
			_audioGroupDict.TryGetValue(data.Group, out menu);
			if (menu != null)
			{
				menu.AddItem(string.Format("{0}:{1}", data.Label, playEventId), reference =>
				{
					if (AudioManager.Instance.FindAudioData(data.BankName) == null)
						AudioManager.Instance.Load(new AudioManager.LoadParam { bankName = data.BankName }, audioData => PlayVoice(playEventId, stopEventId));
					else
						PlayVoice(playEventId, stopEventId);
				}, null, null);
			}
		}

		_seStopMenu = DebugMenu.Create("停止", audioMenu);

		var volumeMenu = DebugMenu.Create("ボリューム", audioMenu);
		volumeMenu.AddSlider("BGM", () => AudioManager.Instance.GetVolume(AudioManager.ListenerType.Bgm), volume => AudioManager.Instance.SetVolume(AudioManager.ListenerType.Bgm, volume), 0.0f, 1.0f);
		volumeMenu.AddSlider("SE", () => AudioManager.Instance.GetVolume(AudioManager.ListenerType.Se), volume => AudioManager.Instance.SetVolume(AudioManager.ListenerType.Se, volume), 0.0f, 1.0f);
		volumeMenu.AddSlider("VOICE", () => AudioManager.Instance.GetVolume(AudioManager.ListenerType.Voice), volume => AudioManager.Instance.SetVolume(AudioManager.ListenerType.Voice, volume), 0.0f, 1.0f);
	}
